import React, { createContext, useContext, useState, useEffect, useCallback } from 'react';
import { useNavigate } from 'react-router-dom';
import axios from 'axios';

const API_URL = process.env.REACT_APP_API_URL || 'http://localhost:8000/api';

const AuthContext = createContext(null);

export const AuthProvider = ({ children }) => {
  const [user, setUser] = useState(null);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState(null);
  const navigate = useNavigate();

  // Initialize axios instance with auth token
  const api = axios.create({
    baseURL: API_URL,
    headers: {
      'Content-Type': 'application/json',
    },
  });

  // Add request interceptor to add auth token to requests
  api.interceptors.request.use(
    (config) => {
      const token = localStorage.getItem('access_token');
      if (token) {
        config.headers['Authorization'] = `Bearer ${token}`;
      }
      return config;
    },
    (error) => {
      return Promise.reject(error);
    }
  );

  // Add response interceptor to handle token refresh
  api.interceptors.response.use(
    (response) => response,
    async (error) => {
      const originalRequest = error.config;

      // If error is 401 and we haven't tried to refresh yet
      if (error.response.status === 401 && !originalRequest._retry) {
        originalRequest._retry = true;

        try {
          const refreshToken = localStorage.getItem('refresh_token');
          if (!refreshToken) {
            // No refresh token, log out
            logout();
            return Promise.reject(error);
          }

          // Try to refresh the token
          const response = await axios.post(`${API_URL}/auth/refresh-token`, {
            refresh_token: refreshToken
          });

          const { access_token, refresh_token } = response.data;

          // Update tokens in localStorage
          localStorage.setItem('access_token', access_token);
          if (refresh_token) {
            localStorage.setItem('refresh_token', refresh_token);
          }

          // Update the authorization header
          originalRequest.headers['Authorization'] = `Bearer ${access_token}`;

          // Retry the original request
          return api(originalRequest);
        } catch (err) {
          // Refresh token failed, log out
          logout();
          return Promise.reject(err);
        }
      }

      return Promise.reject(error);
    }
  );

  // Check if user is authenticated on initial load
  const checkAuth = useCallback(async () => {
    setIsLoading(true);
    const token = localStorage.getItem('access_token');

    if (!token) {
      setIsLoading(false);
      return;
    }

    try {
      // Add retry logic for rate limiting
      let retries = 3;
      let lastError;

      while (retries > 0) {
        try {
          const response = await api.get('/auth/me');
          setUser(response.data);
          return; // Success, exit the function
        } catch (err) {
          lastError = err;

          // If rate limited, wait and retry
          if (err.response?.status === 429) {
            await new Promise(resolve => setTimeout(resolve, 1000));
            retries--;
            continue;
          }

          // For other errors, break the retry loop
          break;
        }
      }

      // If we get here, all retries failed or we got a non-429 error
      console.error('Authentication check failed after retries:', lastError);
      throw lastError;

    } catch (err) {
      console.error('Authentication check failed:', err);
      // Only clear tokens if it's an auth error
      if (err.response?.status === 401 || err.response?.status === 403) {
        localStorage.removeItem('access_token');
        localStorage.removeItem('refresh_token');
      }
      setUser(null);
    } finally {
      setIsLoading(false);
    }
  }, [api]);

  useEffect(() => {
    checkAuth();
  }, [checkAuth]);

  const login = async (email, password) => {
    try {
      setError(null);
      // Clear any previous tokens to ensure a clean state
      localStorage.removeItem('access_token');
      localStorage.removeItem('refresh_token');

      const response = await api.post('/auth/token', new URLSearchParams({
        username: email,
        password: password,
      }), {
        headers: {
          'Content-Type': 'application/x-www-form-urlencoded',
        },
      });

      const { access_token, refresh_token, user: userData } = response.data;

      if (!access_token) {
        throw new Error('No access token received');
      }

      // Store tokens
      localStorage.setItem('access_token', access_token);
      if (refresh_token) {
        localStorage.setItem('refresh_token', refresh_token);
      }

      // Update user state
      setUser(userData);

      // Return user data without redirecting
      // The component will handle the navigation after successful login
      return userData;
    } catch (err) {
      console.error('Login error:', err);
      let errorMessage = 'Incorrect email or password. Please try again.';

      // Handle specific error cases
      if (err.response) {
        // The request was made and the server responded with a status code
        // that falls out of the range of 2xx
        if (err.response.status === 401) {
          errorMessage = 'Incorrect email or password. Please try again.';
        } else if (err.response.status === 403) {
          errorMessage = 'Account is inactive. Please contact support.';
        } else if (err.response.data && err.response.data.detail) {
          errorMessage = err.response.data.detail;
        }
      } else if (err.request) {
        // The request was made but no response was received
        errorMessage = 'Unable to connect to the server. Please check your connection and try again.';
      }

      setError(errorMessage);
      throw new Error(errorMessage);
    }
  };

  const logout = () => {
    // Clear tokens and user data
    localStorage.removeItem('access_token');
    localStorage.removeItem('refresh_token');
    setUser(null);

    // Redirect to login page
    navigate('/login');
  };

  const register = async (userData) => {
    try {
      setError(null);
      const response = await api.post('/auth/register', userData);

      // Auto-login after registration
      if (userData.password) {
        await login(userData.email, userData.password);
      }

      return response.data;
    } catch (err) {
      console.error('Registration error:', err);
      const errorMessage = err.response?.data?.detail || 'Registration failed. Please try again.';
      setError(errorMessage);
      throw new Error(errorMessage);
    }
  };

  const value = {
    user,
    isAuthenticated: !!user,
    isLoading,
    error,
    setError, // Expose setError to allow components to clear errors
    login,
    logout,
    register,
    api, // Export the configured axios instance
  };

  return (
    <AuthContext.Provider value={value}>
      {!isLoading && children}
    </AuthContext.Provider>
  );
};

export const useAuth = () => {
  const context = useContext(AuthContext);
  if (!context) {
    throw new Error('useAuth must be used within an AuthProvider');
  }
  return context;
};
